    const renderAudit=()=>{body.innerHTML=`<section class="panel"><h2>Bitácora</h2><table><thead><tr><th>Fecha</th><th>Usuario</th><th>Acción</th><th>Entidad</th><th>Detalle</th></tr></thead><tbody>${[...M.db.auditLog].reverse().slice(0,300).map(l=>`<tr><td>${new Date(l.at).toLocaleString()}</td><td>${M.escape(l.userId)}</td><td>${M.escape(l.action)}</td><td>${M.escape(l.entityType)} ${M.escape(l.entityId)}</td><td>${M.escape(l.detail)}</td></tr>`).join('')}</tbody></table></section>`};
