  M.printMAR=(areaId)=>{const y=M.currentYear(),area=M.db.areas.find(a=>a.id===areaId),rs=M.db.risks.filter(r=>!r.isDeleted&&r.areaId===areaId&&r.exercise===y);M.view.innerHTML=`<div class="page-head no-print"><h1>MAR imprimible</h1><div><button class="btn" id="backRep">Volver</button> <button class="btn primary" id="doPrint">Imprimir / PDF</button></div></div><section class="report-sheet landscape"><div class="report-head"><img src="data:image/png;base64,"><div><b>TRIBUNAL ELECTORAL DE LA CIUDAD DE MÉXICO</b><span>${M.escape(M.areaLabel(area))}</span><strong>MATRIZ DE ADMINISTRACIÓN DE RIESGOS ${y}</strong></div></div><table class="mar-table"><thead><tr><th>No.</th><th>OBJETIVO</th><th>RIESGO</th><th>FACTORES DE RIESGO</th><th>CONTROLES</th><th>INDICADORES</th></tr></thead><tbody>${rs.map(r=>`<tr><td>${r.localId}</td><td>${M.escape(r.objective)}</td><td>${M.escape(r.risk)}</td><td>${M.escape(r.factors)}</td><td>${M.escape((r.controls||[]).map(c=>c.text).join('; '))}</td><td>${M.escape((r.indicators||[]).map(i=>i.name).join('; '))}</td></tr>`).join('')}</tbody></table>${y===2026?'<p class="footnote">Ejercicio de implementación – septiembre de 2026. Integración retrospectiva de T1, T2 y T3.</p>':''}</section>`;document.querySelector('#backRep').onclick=()=>M.navigate('reports');document.querySelector('#doPrint').onclick=()=>window.print()};
