  function login(){document.body.className='login-page';document.querySelector('#app').innerHTML=`<main class="login-wrap"><section class="login-card"><img src="data:image/png;base64," class="login-logo" alt="TECDMX"><h1>Sistema de Administración de Riesgos</h1><p>Mapas de Riesgos · MAR · POA · Seguimiento</p><form id="loginForm"><label>Usuario<input class="input" name="username" autocomplete="username" required></label><label>Contraseña<input class="input" type="password" name="password" autocomplete="current-password" required></label><div id="loginError" class="error"></div><button class="btn primary full" type="submit">Ingresar</button></form><details><summary>Acceso inicial</summary><p><b>Administrador:</b> admin / Admin2026!</p><p><b>Demo DPyRF:</b> demo / Demo2026!</p></details></section></main>`;document.querySelector('#loginForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);const s=await M.authenticate(f.get('username'),f.get('password'));if(!s){document.querySelector('#loginError').textContent='Usuario o contraseña incorrectos.';return}M.session=s;sessionStorage.setItem('mar.session',JSON.stringify(s));M.renderShell();M.navigate('dashboard')}}
