 acts.forEach(a=>{const ars=links.get(a.id)||[];if(!ars.length)return;const aset=new Set(ars.map(r=>r.localId));let best=null,nmax=0;groups.forEach(g=>{const n=g.risks.reduce((n,r)=>n+(aset.has(r.localId)?1:0),0);if(n>nmax){nmax=n;best=g}});if(best)best.actions.push(a)});
